bool subset(const V& v,const V& e){if(e.isObject()){if(!v.isObject())return false;for(const auto& x:e.object()){const auto* p=v.find(x.first);if(!p||!subset(*p,x.second))return false;}return true;}if(e.isArray()){if(!v.isArray()||v.array().size()!=e.array().size())return false;for(std::size_t i=0;i<e.array().size();++i)if(!subset(v.array()[i],e.array()[i]))return false;return true;}return v==e;}
