bool validDate(const std::string& s){if(s.size()!=10||s[4]!='-'||s[7]!='-')return false;for(std::size_t i=0;i<s.size();++i)if(i!=4&&i!=7&&(s[i]<'0'||s[i]>'9'))return false;const int y=std::stoi(s.substr(0,4)),m=std::stoi(s.substr(5,2)),d=std::stoi(s.substr(8,2));if(y<1||m<1||m>12)return false;const int days[12]={31,28,31,30,31,30,31,31,30,31,30,31};return d>=1&&d<=days[m-1]+(m==2&&y%4==0&&(y%100!=0||y%400==0));}
